# Generated by ROS 2 Humble Setup

$ErrorActionPreference = 'Stop'

function Get-RosProcesses([string] $Root) {
    $prefix = $Root.TrimEnd('\') + '\'
    $shellFolder = Join-Path $Root '.ros2-shells'
    $rosLauncher = [regex]::Escape((Join-Path $Root 'ros-humble.cmd'))
    $receiverLauncher = [regex]::Escape((Join-Path $Root 'pointcloud_receiver\start-receiver.cmd'))
    foreach ($process in Get-CimInstance -ClassName Win32_Process -Filter "Name = 'cmd.exe'" -Property ProcessId, CreationDate, CommandLine -OperationTimeoutSec 5) {
        $record = Join-Path $shellFolder "$($process.ProcessId).txt"
        if ($process.CommandLine -match ('(?:^|[\s"])' + $receiverLauncher + '(?=[\s"]|$)')) {
            "WalkableOR receiver terminal (PID $($process.ProcessId))"
        }
        elseif ($process.CommandLine -match ('(?:^|[\s"])' + $rosLauncher + '(?=[\s"]|$)') -or
            ($process.CreationDate -and [IO.File]::Exists($record) -and
                [IO.File]::ReadAllText($record) -eq $process.CreationDate.ToUniversalTime().Ticks.ToString())) {
            "ROS command prompt (PID $($process.ProcessId))"
        }
    }
    foreach ($process in Get-CimInstance -ClassName Win32_Process -Property Name, ProcessId, ExecutablePath -OperationTimeoutSec 5) {
        if ($process.ExecutablePath -and
            $process.ExecutablePath.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase)) {
            "$($process.Name) (PID $($process.ProcessId))"
        }
    }
}

# Dot-sourcing exposes the scanner to the uninstaller without registering its shell.
if ($MyInvocation.InvocationName -eq '.') { return }

$self = Get-CimInstance -ClassName Win32_Process -Filter "ProcessId = $PID" -OperationTimeoutSec 5
$shell = Get-CimInstance -ClassName Win32_Process -Filter "ProcessId = $($self.ParentProcessId)" -OperationTimeoutSec 5
if ($shell.Name -ine 'cmd.exe' -or !$shell.CreationDate -or $shell.CreationDate -gt $self.CreationDate) {
    throw 'Could not identify the current ROS command prompt.'
}

$folder = Join-Path $PSScriptRoot '.ros2-shells'
$directory = [IO.Directory]::CreateDirectory($folder)
if ($directory.Attributes -band [IO.FileAttributes]::ReparsePoint) {
    throw "The shell registration folder is a link: $folder"
}
$record = Join-Path $folder "$($shell.ProcessId).txt"
$created = $shell.CreationDate.ToUniversalTime().Ticks.ToString()
if ([IO.File]::Exists($record) -and [IO.File]::ReadAllText($record) -eq $created) { return }
$temporary = Join-Path $folder "$([Guid]::NewGuid().ToString('N')).tmp"
try {
    [IO.File]::WriteAllText($temporary, $created)
    if ([IO.File]::Exists($record)) { [IO.File]::Replace($temporary, $record, [NullString]::Value) }
    else { [IO.File]::Move($temporary, $record) }
}
finally { [IO.File]::Delete($temporary) }
